import{_ as t,o as a,c as r,ai as n}from"./chunks/framework.BBSijY9B.js";const h=JSON.parse('{"title":"DeepSeek 开源推理引擎 DeepInfer","description":"","frontmatter":{"title":"DeepSeek 开源推理引擎 DeepInfer","date":"2026-10-20T00:00:00.000Z","summary":"DeepSeek 把线上服务用的推理引擎开源了（Apache-2.0），首发支持 DeepSeek-V4.1-Flash，硬件支持 NVIDIA SM100 和华为昇腾 950；KV cache、PD 分离和负载均衡没有放出来。","category":"好项目","tags":["开源","大模型","DeepSeek"],"sources":[{"url":"https://github.com/deepseek-ai/DeepInfer","author":"deepseek-ai/DeepInfer（GitHub）","platform":"GitHub"},{"url":"https://x.com/IMWANGXXXL/status/2112510228482904383","author":"@IMWANGXXXL 的解读","platform":"X"}],"wordCount":312,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"DeepSeek 开源推理引擎 DeepInfer | 王宇宙 | WANGXXXL"}],["meta",{"property":"og:description","content":"DeepSeek 把线上服务用的推理引擎开源了（Apache-2.0），首发支持 DeepSeek-V4.1-Flash，硬件支持 NVIDIA SM100 和华为昇腾 950；KV cache、PD 分离和负载均衡没有放出来。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/daily/2026-10-20-deepinfer"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/daily-2026-10-20-deepinfer-e1437dd3dc.png"}],["meta",{"property":"og:image:alt","content":"DeepSeek 开源推理引擎 DeepInfer · 王宇宙 | WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"DeepSeek 开源推理引擎 DeepInfer | 王宇宙 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"DeepSeek 把线上服务用的推理引擎开源了（Apache-2.0），首发支持 DeepSeek-V4.1-Flash，硬件支持 NVIDIA SM100 和华为昇腾 950；KV cache、PD 分离和负载均衡没有放出来。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/daily-2026-10-20-deepinfer-e1437dd3dc.png"}],["meta",{"name":"twitter:image:alt","content":"DeepSeek 开源推理引擎 DeepInfer · 王宇宙 | WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/daily/2026-10-20-deepinfer"}]]},"headers":[],"relativePath":"daily/2026-10-20-deepinfer.md","filePath":"daily/2026-10-20-deepinfer.md","lastUpdated":1792499664000}'),o={name:"daily/2026-10-20-deepinfer.md"};function p(i,e,l,c,s,d){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="deepseek-开源推理引擎-deepinfer" tabindex="-1">DeepSeek 开源推理引擎 DeepInfer <a class="header-anchor" href="#deepseek-开源推理引擎-deepinfer" aria-label="Permalink to &quot;DeepSeek 开源推理引擎 DeepInfer&quot;">​</a></h1><h2 id="发生了什么" tabindex="-1">发生了什么 <a class="header-anchor" href="#发生了什么" aria-label="Permalink to &quot;发生了什么&quot;">​</a></h2><p>DeepSeek 开源了 <a href="https://github.com/deepseek-ai/DeepInfer" target="_blank" rel="noopener noreferrer">DeepInfer</a>，许可证 Apache-2.0。按 README 的说法，它就是 DeepSeek 线上大规模服务用的推理框架，这次放出的是离线推理部分。</p><ul><li><strong>支持的模型</strong>：DeepSeek-V4.1-Flash。</li><li><strong>硬件</strong>：NVIDIA SM100 系列 GPU 和华为昇腾 950 NPU。</li><li><strong>主要特性</strong>：优化过的计算内核；注意力和 MoE 的多种并行方式；DSpark 投机解码，默认最多 5 个草稿 token；结构化输出（正则、JSON Schema、EBNF）；在 NVIDIA 上支持确定性采样。</li><li><strong>没有放出来的</strong>：KV cache 系统、Prefill/Decode 分离部署、多副本之间的负载均衡。完整的线上服务还需要这几块。</li></ul><h2 id="对你有什么用" tabindex="-1">对你有什么用 <a class="header-anchor" href="#对你有什么用" aria-label="Permalink to &quot;对你有什么用&quot;">​</a></h2><ul><li><strong>个人和小团队基本用不上</strong>：硬件门槛很高，也缺上面几块组件。</li><li><strong>值得看的是思路</strong>：它把「大模型推理怎么省钱」摊开了，想了解为什么有的模型能卖得便宜，可以看 README 里的特性说明和 Performance benchmarks 一节（测试用的是 4 张 SM100 做 prefill、64 张做 decode）。</li><li>想自己跑开源模型，个人电脑上更现实的选择是 <a href="https://github.com/ollama/ollama" target="_blank" rel="noopener noreferrer">Ollama</a>，见<a href="/resources/?tab=projects">资源导航 · 开源项目</a>。</li></ul>',6)])])}const D=t(o,[["render",p]]);export{h as __pageData,D as default};
